export type ErrorKind = "network" | "http" | "unknown";
export class ClientError extends Error {
  kind: ErrorKind;
  constructor(message: string, kind: ErrorKind, cause?: unknown) {
    super(message, {cause});
    this.name = "ClientError";
    this.kind = kind;
  }
}
export async function request(fetcher: () => Promise<{status: number; body: string}>): Promise<string> {
  let response;
  try { response = await fetcher(); }
  catch (error) {
    throw new ClientError("request failed: " + (error instanceof Error ? error.message : String(error)), error instanceof Error ? "network" : "unknown", error);
  }
  if (response.status >= 400) throw new ClientError("HTTP " + response.status, "http", response);
  return response.body;
}
